 "claims": [
  {
   "claim": "Marco's lunchbox is out of the house during his work shift",
   "target": "lunchbox_marco",
   "expect": "OUT_OF_HOUSE",
   "days": "weekday",
   "from": 14,
   "to": 22
  },
  {
   "claim": "Yuki's keys remain at the entry table during her morning walk",
   "target": "keys_yuki",
   "expect": "entry_table_e1",
   "days": "weekday",
   "from": 7,
   "to": 8.5
  },
  {
